-- PT110-S3-Q8. Batch 05.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT110-S3-Q8$batch05$ AND q.stimulus=$batch05$Dr. Jones: The new technology dubbed "telemedicine" will provide sustained improvement in at least rural patient care since it allows rural physicians to televise medical examinations to specialists who live at great distances-specialists who will thus be able to provide advice the rural patient would otherwise not receive.

Dr. Carabella: Not so. Telemedicine might help rural patient care initially. However, small hospitals will soon realize that they can minimize expenses by replacing physicians with technicians who can use telemedicine to transmit examinations to large medical centers, resulting in fewer patients being able to receive traditional, direct medical examination. Eventually, it will be the rare individual who ever gets truly personal attention. Hence, rural as well as urban patient care will suffer.$batch05$ AND q.prompt=$batch05$Dr. Carabella uses which one of the following strategies in responding to Dr. Jones?$batch05$ AND q.correct_choice=$batch05$B$batch05$) THEN RAISE EXCEPTION 'Question changed: PT110-S3-Q8'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch05$PT110-S3-Q8$batch05$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT110-S3-Q8'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT110-S3-Q8$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$(Dr. Carabella) Telemedicine will make rural and urban patient care worse.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$Hospitals will replace physicians with technicians who transmit exams to big centers. Fewer patients will get direct examinations, and eventually few will get truly personal attention.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$Carabella grants the first step ("might help rural patient care initially"), then follows a chain of events forward. Telemedicine starts the chain, and the chain ends somewhere bad. When a response says "this starts a process that ends badly," that is the shape to look for.$batch05$), (3, $batch05$Goal$batch05$, $batch05$Describing telemedicine as the first step in a process that leads to a bad result.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT110-S3-Q8$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$This is the most popular wrong answer, because it is the closest in wording: something that seems to help ends up hurting. But Carabella is not talking about a treatment given to *a* patient. She describes how hospitals will change over time. A list of considerations about one patient is not that.$batch05$), ($batch05$B$batch05$, $batch05$The step is applying telemedicine. The process is hospitals swapping physicians for technicians. The undesirable end is worse care for everyone.$batch05$), ($batch05$C$batch05$, $batch05$Carabella never questions Dr. Jones's training.$batch05$), ($batch05$D$batch05$, $batch05$No statistics, and Carabella does not dispute Jones's premises.$batch05$), ($batch05$E$batch05$, $batch05$No key term is reinterpreted.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT110-S3-Q8$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
